import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"তল তত্ত্ব ও শ্রেণীবিভাগ","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0080-位面理论与分类.md","filePath":"bn/0080-位面理论与分类.md"}'),e={name:"bn/0080-位面理论与分类.md"};function l(h,t,i,n,u,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="তল-তত্ত্ব-ও-শ্রেণীবিভাগ" tabindex="-1">তল তত্ত্ব ও শ্রেণীবিভাগ <a class="header-anchor" href="#তল-তত্ত্ব-ও-শ্রেণীবিভাগ" aria-label="Permalink to &quot;তল তত্ত্ব ও শ্রেণীবিভাগ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>80</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>তল তত্ত্ব, তল শ্রেণীবিভাগ, আইন প্রাচীর, তল স্থানাঙ্ক, হেংইয়ান-ঝৌ</td></tr></tbody></table><h2 id="_1-তলের-মৌলিক-সংজ্ঞা" tabindex="-1">1. তলের মৌলিক সংজ্ঞা <a class="header-anchor" href="#_1-তলের-মৌলিক-সংজ্ঞা" aria-label="Permalink to &quot;1. তলের মৌলিক সংজ্ঞা&quot;">​</a></h2><p>মহাপ্রাণ বাল অ্যাঙ্কর মূল মহাবিশ্ব (হেংইয়ান-ঝৌ) এর কাঠামোর অধীনে, &quot;তল&quot; বলতে একটি অপেক্ষাকৃত স্থির আইনের সেট দ্বারা সীমাবদ্ধ, স্বাধীন স্থান-কালের ধারাবাহিকতা সম্পন্ন অস্তিত্বের অঞ্চলকে বোঝায়। তল কেবল &quot;অন্য একটি বিশ্ব&quot; নয়, বরং বিভিন্ন প্যারামিটার অন্তরালে আইন নেটওয়ার্কের সংস্থাপিত প্রজেকশন। প্রতিটি তলের নিজস্ব অনন্য ভৌত ধ্রুবক, শক্তির ঘনত্ব, সময়ের প্রবাহের গতি ও চেতনার সক্রিয়তা রয়েছে, এই প্যারামিটারগুলি একসাথে该 তলের &quot;আইন ফিঙ্গারপ্রিন্ট&quot; গঠন করে।</p><p>তলের অস্তিত্ব হেংইয়ান-ঝৌর আইন নেটওয়ার্কের অ-সমানতা থেকে উদ্ভূত। মহাবিশ্বের মূল আইন চলার প্রক্রিয়াতে, শক্তির বিতরণ, চেতনার ব্যাঘাত ও ঐতিহাসিক বিবর্তনের পার্থক্যের কারণে, স্বাভাবিকভাবেই অসংখ্য বিভিন্ন প্যারামিটারের আইন অঞ্চল তৈরি হয়। এই অঞ্চলগুলির মধ্যে &quot;আইন প্রাচীর&quot; দ্বারা পৃথক করা হয়, প্রাচীরের শক্তি সন্নিহিত তলগুলির মধ্যে আইন প্যারামিটারের পার্থক্যের মাত্রার উপর নির্ভর করে — পার্থক্য যত বেশি, প্রাচীর তত পুরু, অতিক্রম করার কঠিনতা তত বেশি।</p><p>অ্যাঙ্কর মেকানিজম তল তত্ত্বে মূল অবস্থান দখল করে। অ্যাঙ্কর মূলত আইন নেটওয়ার্কের স্থির নোড, এটি শুধুমাত্র নিজের তলের আইনের স্থিতিশীলতা বজায় রাখতে পারে না, বরং আন্তঃ-তল সংযোগের অ্যাঙ্করিং মানদণ্ড হিসেবেও কাজ করতে পারে। আন্তঃ-তল অতিক্রম, যোগাযোগ ও প্রত্নতত্ত্ব ইত্যাদি সব মিথস্ক্রিয়া আচরণ, অবশ্যই অ্যাঙ্করকে স্থানাঙ্কের উৎস হিসেবে নিয়ে অবস্থান ও অ্যালাইনমেন্ট করতে হবে।</p><h2 id="_2-তল-শ্রেণীবিভাগ-ব্যবস্থা" tabindex="-1">2. তল শ্রেণীবিভাগ ব্যবস্থা <a class="header-anchor" href="#_2-তল-শ্রেণীবিভাগ-ব্যবস্থা" aria-label="Permalink to &quot;2. তল শ্রেণীবিভাগ ব্যবস্থা&quot;">​</a></h2><p>হেংইয়ান-ঝৌর ভেতরের তলগুলি আইন প্যারামিটার, শক্তির স্তর ও সভ্যতার বিকাশের মাত্রা অনুযায়ী, নিম্নলিখিত পাঁচটি বিভাগে বিভক্ত:</p><table tabindex="0"><thead><tr><th>বিভাগ</th><th>আইনের বৈশিষ্ট্য</th><th>শক্তির ঘনত্ব</th><th>সাধারণ সভ্যতার রূপ</th><th>অতিক্রমের কঠিনতা</th></tr></thead><tbody><tr><td>পদার্থ মূল তল</td><td>ভৌত আইন প্রধান, শক্তি অপ্রকাশিত</td><td>কম</td><td>প্রযুক্তি সভ্যতা, প্রাথমিক সাধনা সভ্যতা</td><td>কম</td></tr><tr><td>শক্তি প্রকাশ তল</td><td>শক্তি আইন অর্ধ-প্রকাশিত, সাধনা ব্যবস্থা পরিপক্ক</td><td>মাঝারি</td><td>মধ্য-উচ্চ সাধনা সভ্যতা, জাদু সভ্যতা</td><td>মাঝারি</td></tr><tr><td>চেতনা প্রধান তল</td><td>চেতনা আইন প্রকাশিত, পদার্থ চেতনা দ্বারা রূপান্তরিত</td><td>উচ্চ</td><td>আত্মিক সত্তা সভ্যতা, চেতনা সমষ্টি সভ্যতা</td><td>উচ্চ</td></tr><tr><td>আইন ভাঙা তল</td><td>আইন অস্থির, প্রচুর আইন ফাটল বিদ্যমান</td><td>অত্যন্ত উচ্চ ও বিশৃঙ্খল</td><td>পুরানো তল, ধ্বংসস্তূপ তল</td><td>অত্যন্ত উচ্চ</td></tr><tr><td>মূল নিকটবর্তী তল</td><td>মহাবিশ্বের মূল আইনের নিকট, প্যারামিটার সীমার কাছাকাছি</td><td>মূলের কাছাকাছি</td><td>সর্বোচ্চ সভ্যতা, তল রক্ষক</td><td>তাত্ত্বিক সীমা</td></tr></tbody></table><p>উপরোক্ত পাঁচটি বিভাগ ছাড়াও, কিছু বিশেষ তলের প্রকারও বিদ্যমান, যার মধ্যে অন্তর্ভুক্ত: প্রতিচ্ছবি তল (কোনো এক তলের আইন প্যারামিটারের সাথে অত্যন্ত প্রতিসম সমান্তরাল অস্তিত্ব), স্তরান্তর তল (দুটি প্রধান তলের আইন প্রাচীরের মধ্যে অবস্থিত সংক্রমণ অঞ্চল), সুপ্ত তল (আইনের সক্রিয়তা অত্যন্ত কম, প্রায় স্থবির প্রাচীন তল) এবং নবজাত তল (আইন নেটওয়ার্ক সম্প্রতি গঠিত, প্যারামিটার এখনও স্থির নয় এমন তরুণ তল)।</p><h2 id="_3-তল-স্থানাঙ্ক-ও-অবস্থান-নির্ণয়ের-নীতি" tabindex="-1">3. তল স্থানাঙ্ক ও অবস্থান নির্ণয়ের নীতি <a class="header-anchor" href="#_3-তল-স্থানাঙ্ক-ও-অবস্থান-নির্ণয়ের-নীতি" aria-label="Permalink to &quot;3. তল স্থানাঙ্ক ও অবস্থান নির্ণয়ের নীতি&quot;">​</a></h2><p>আন্তঃ-তল মিথস্ক্রিয়ার পূর্বশর্ত হলো সুনির্দিষ্ট তল অবস্থান নির্ণয়। হেংইয়ান-ঝৌ অ্যাঙ্করকে মানদণ্ড হিসেবে &quot;চার-মাত্রিক তল স্থানাঙ্ক ব্যবস্থা&quot; প্রতিষ্ঠা করেছে, প্রতিটি তল চারটি প্যারামিটার দ্বারা অনন্যভাবে নির্ধারিত:</p><ol><li><strong>আইন ফিঙ্গারপ্রিন্ট কোড</strong>:该 তলের মূল আইন প্যারামিটার হ্যাশ অপারেশনের মাধ্যমে উৎপন্ন অনন্য শনাক্তকারী, দৈর্ঘ্য 128 বিট</li><li><strong>অ্যাঙ্কর সম্পর্কযোগ্যতা</strong>:该 তলের পরিচিত অ্যাঙ্কর নেটওয়ার্কের সাথে সংযোগের শক্তি, মানের পরিসর 0 থেকে 1</li><li><strong>সময়ের প্রবাহের অনুপাত</strong>:该 তলের সময়ের প্রবাহের গতি ও হেংইয়ান-ঝৌর মানক সময়ের অনুপাত, সাধারণ পরিসর 0.1 থেকে 10</li><li><strong>স্থানের মাত্রার সংখ্যা</strong>:该 তলের উপলব্ধিযোগ্য স্থানের মাত্রার সংখ্যা, সাধারণত 3 থেকে 11 মাত্রা</li></ol><p>তল স্থানাঙ্ক প্রাপ্তির উপায় অন্তর্ভুক্ত: অ্যাঙ্কর নেটওয়ার্ক স্বয়ংক্রিয় অনুসন্ধান, আন্তঃ-তল যোগাযোগ সংকেত পুনরুদ্ধার, প্রত্নতাত্ত্বিক ধ্বংসস্তূপে স্থানাঙ্কের অবশিষ্টাংশ এবং তল অতিক্রমকারীর ম্যানুয়াল রেকর্ড। সব নিশ্চিত তল স্থানাঙ্ক &quot;হেংইয়ান-ঝৌ তল স্থানাঙ্ক মূল কোষ&quot; এ录 করা হয়, অ্যাঙ্কর কাউন্সিলের অধীনস্থ তল ব্যবস্থাপনা ব্যুরো দ্বারা ঐক্যবদ্ধভাবে রক্ষণাবেক্ষণ করা হয়।</p><h2 id="_4-তলগুলির-মধ্যে-প্রাকৃতিক-মিথস্ক্রিয়া" tabindex="-1">4. তলগুলির মধ্যে প্রাকৃতিক মিথস্ক্রিয়া <a class="header-anchor" href="#_4-তলগুলির-মধ্যে-প্রাকৃতিক-মিথস্ক্রিয়া" aria-label="Permalink to &quot;4. তলগুলির মধ্যে প্রাকৃতিক মিথস্ক্রিয়া&quot;">​</a></h2><p>এমনকি সক্রিয় অতিক্রম আচরণ না থাকলেও, তলগুলির মধ্যে প্রাকৃতিক মিথস্ক্রিয়ার ঘটনা বিদ্যমান। সবচেয়ে সাধারণ হলো &quot;আইন ফুটো&quot; — সন্নিহিত তলগুলির মধ্যে প্রাচীরের স্থানীয় দুর্বলতার কারণে, অল্প পরিমাণে আইন প্যারামিটার পরস্পর অনুপ্রবেশ করে, স্থানীয় অস্বাভাবিক ঘটনা সৃষ্টি করে। যেমন পদার্থ মূল তলে মাঝে মাঝে দেখা যায় &quot;অতিপ্রাকৃতিক ঘটনা&quot;, প্রায়শই পার্শ্ববর্তী শক্তি প্রকাশ তলের আইন ফুটোর কারণে হয়।</p><p>অন্য একটি প্রাকৃতিক মিথস্ক্রিয়া হলো &quot;তলের অনুরণন&quot;। যখন দুটি তলের আইন ফিঙ্গারপ্রিন্ট কোডে উচ্চ মাত্রার মিল থাকে, তখন তাদের মধ্যে পর্যায়ক্রমিক আইন অনুরণন তৈরি হয়, যা প্রকাশ পায় দুটি তলে নির্দিষ্ট সময়ের মধ্যে অনুরূপ ঐতিহাসিক ঘটনা, সভ্যতার গতিপথ এমনকি ব্যক্তিত্বের ভাগ্যের মাধ্যমে। তলের অনুরণন হলো তল প্রত্নতত্ত্ববিদ্যার গুরুত্বপূর্ণ গবেষণার বিষয়, অনুরণনের নিয়ম বিশ্লেষণের মাধ্যমে অজানা তলের সভ্যতার অবস্থা অনুমান করা যায়।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>তল তত্ত্ব হলো আন্তঃ-তল মিথস্ক্রিয়ার সব অনুশীলনের তাত্ত্বিক ভিত্তি। তলের সত্তা, শ্রেণীবিভাগ ও অবস্থান নির্ণয়ের নীতি সঠিকভাবে বোঝা, অতিক্রম নিয়ম, নৈতিক নীতি ও প্রতিরোধ ব্যবস্থা প্রণয়নের পূর্বশর্ত। হেংইয়ান-ঝৌর তল অনুসন্ধান সর্বদা &quot;জ্ঞান আগে, মিথস্ক্রিয়া সতর্কতার সাথে&quot; এর নীতি অনুসরণ করে, সভ্যতার সীমানা প্রসারিত করার সাথে সাথে, কোনো তলের স্বায়ত্তশাসিত বিবর্তনে অপরিবর্তনীয় ব্যাঘাত সৃষ্টি না করা নিশ্চিত করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>81-তল অতিক্রম নিয়ম</li><li>88-আন্তঃ-তল নৈতিক নীতি</li><li>28-আন্তঃ-তল অ্যাঙ্কর সংযোগ</li></ul>',21)])])}const p=d(e,[["render",l]]);export{q as __pageData,p as default};
